import { User } from "./models/index";
import { render } from "./views/render";
import { fetchUsers } from "./services/api";
import { log } from "./util/events";
import "./legacy/polyfills";

var users = [];

export function start(root) {
  log("start");
  fetchUsers().then(function (list) {
    users = list.map(function (item) {
      return new User(item.name);
    });
    render(root, users);
  });
}

import { ENV } from "~/config/env";

export var settings = {
  baseUrl: ENV === "production" ? "https://shop.example.test/api" : "http://localhost:3000/api",
};

import "../util/strings";

if (!String.prototype.startsWith) {
  String.prototype.startsWith = function (prefix) {
    return this.indexOf(prefix) === 0;
  };
}

import { User } from "./user";

export function Account(owner) {
  this.owner = owner;
  this.kind = "basic";
}

Account.prototype.isOwnedBy = function (user) {
  return user instanceof User && user === this.owner;
};

export * from "./user";
export * from "./account";
export * from "./session";

import { User } from "./user";

var current = null;

export function signIn(name) {
  current = new User(name);
  return current;
}

export function signOut() {
  current = null;
}

import { Account } from "./account";

export function User(name) {
  this.name = name;
  this.account = new Account(this);
}

User.prototype.label = function () {
  return this.name + " (" + this.account.kind + ")";
};

import { settings } from "../config/settings";
import { pad } from "../util/strings";

export function fetchUsers() {
  var stamp = pad(new Date().getMonth() + 1, 2);
  return fetch(settings.baseUrl + "/users?month=" + stamp).then(function (response) {
    return response.json();
  });
}

import { settings } from "../config/settings";

export function save(key, value) {
  localStorage.setItem(settings.baseUrl + key, JSON.stringify(value));
}

import * as self from "./events";

var handlers = {};

export function on(name, handler) {
  handlers[name] = handler;
}

export function log(message) {
  self.on("log", function () {});
  if (handlers.log) handlers.log(message);
}

export function pad(value, width) {
  var text = String(value);
  while (text.length < width) text = "0" + text;
  return text;
}

import { buildTable } from "./widgets/table";
import { buildForm } from "./widgets/form";
import { byId } from "../util/dom";

export function render(rootId, users) {
  var root = byId(rootId);
  root.appendChild(buildTable(users));
  root.appendChild(buildForm());
}

import { countRows } from "./table";

export function buildCell(text) {
  var cell = document.createElement("td");
  cell.textContent = text;
  cell.title = "rows: " + countRows(cell.parentNode || document.createElement("table"));
  return cell;
}

import { formatLabel } from "@/lib/format";

export function buildField(name) {
  var input = document.createElement("input");
  input.name = name;
  input.placeholder = formatLabel(name);
  return input;
}

import { buildField } from "./field";
import { byId } from "../../util/dom";

export function buildForm() {
  var form = document.createElement("form");
  form.appendChild(buildField("name"));
  form.id = byId("main") ? "form-main" : "form";
  return form;
}

import { buildCell } from "./cell";

export function buildRow(user) {
  var row = document.createElement("tr");
  row.appendChild(buildCell(user.name));
  return row;
}

import { buildRow } from "./row";

export function buildTable(users) {
  var table = document.createElement("table");
  users.forEach(function (user) {
    table.appendChild(buildRow(user));
  });
  return table;
}

export function countRows(table) {
  return table.rows.length;
}
